import GoDFoundation

/// Compress one file, or every file in a folder, with a named stream format.
///
/// Not generated by project setup — hand-authored, like `convert`. Nothing
/// here takes an engine folder: the format name and its options fully
/// determine the codec.
enum Compress {

    /// Compress `inputFile`, writing `outputFile` or, when that is absent,
    /// `<inputFile>.<ext>` beside the input.
    struct SingleConfig: Codable {
        let inputFile: File
        let format: CompressionOps.Format
        let outputFile: File?
        let overwrite: Bool
        let options: CompressionOps.Options?

        init(
            inputFile: File,
            format: CompressionOps.Format,
            outputFile: File? = nil,
            overwrite: Bool = true,
            options: CompressionOps.Options? = nil
        ) {
            self.inputFile = inputFile
            self.format = format
            self.outputFile = outputFile
            self.overwrite = overwrite
            self.options = options
        }
    }

    /// Bulk — every file under `inputFolder` that passes the extension
    /// filter is compressed to the same relative path under `outputFolder`,
    /// named `<file>.<ext>`.
    struct BatchConfig: Codable {
        let inputFolder: Folder
        let outputFolder: Folder
        let format: CompressionOps.Format
        let overwrite: Bool
        /// Descend into subfolders. Off by default so a bulk run over one
        /// folder can't quietly walk a whole tree.
        let recursive: Bool
        /// Only files with these extensions (dot optional, case-insensitive).
        /// Absent takes every file.
        let extensions: [String]?
        /// The extension appended to each output. Absent uses the format's
        /// own (`szs`, `szp`, `lzss`).
        let outputExtension: String?
        let options: CompressionOps.Options?

        init(
            inputFolder: Folder,
            outputFolder: Folder,
            format: CompressionOps.Format,
            overwrite: Bool = true,
            recursive: Bool = false,
            extensions: [String]? = nil,
            outputExtension: String? = nil,
            options: CompressionOps.Options? = nil
        ) {
            self.inputFolder = inputFolder
            self.outputFolder = outputFolder
            self.format = format
            self.overwrite = overwrite
            self.recursive = recursive
            self.extensions = extensions
            self.outputExtension = outputExtension
            self.options = options
        }
    }
}

/// Decompress one file, or every recognized file in a folder.
///
/// The format is optional: a stream with a magic says what it is, so a
/// caller that had to name it could only get it wrong. The one exception
/// is `lzss-raw`, which has no magic and must be named.
enum Decompress {

    /// Decompress `inputFile` — or the window of it `range` selects — to
    /// `outputFile` or, when that is absent, a derived name beside the
    /// input: the compressed extension dropped, or `.bin` appended.
    struct SingleConfig: Codable {
        let inputFile: File
        /// Absent detects by magic.
        let format: CompressionOps.Format?
        /// For a stream embedded inside a larger file.
        let range: CompressionOps.ByteRange?
        let outputFile: File?
        let overwrite: Bool
        let options: CompressionOps.Options?

        init(
            inputFile: File,
            format: CompressionOps.Format? = nil,
            range: CompressionOps.ByteRange? = nil,
            outputFile: File? = nil,
            overwrite: Bool = true,
            options: CompressionOps.Options? = nil
        ) {
            self.inputFile = inputFile
            self.format = format
            self.range = range
            self.outputFile = outputFile
            self.overwrite = overwrite
            self.options = options
        }
    }

    /// Bulk — every file under `inputFolder` that passes the extension
    /// filter and carries a recognized magic is decompressed to the same
    /// relative path under `outputFolder`, under its derived name. Files
    /// that aren't streams are skipped and counted, not failed.
    struct BatchConfig: Codable {
        let inputFolder: Folder
        let outputFolder: Folder
        /// Absent takes whatever each file's magic says. A named
        /// self-describing format skips files that aren't it; `lzss-raw`
        /// treats every candidate as a raw stream.
        let format: CompressionOps.Format?
        /// Applied to every file.
        let range: CompressionOps.ByteRange?
        let overwrite: Bool
        let recursive: Bool
        let extensions: [String]?
        let options: CompressionOps.Options?

        init(
            inputFolder: Folder,
            outputFolder: Folder,
            format: CompressionOps.Format? = nil,
            range: CompressionOps.ByteRange? = nil,
            overwrite: Bool = true,
            recursive: Bool = false,
            extensions: [String]? = nil,
            options: CompressionOps.Options? = nil
        ) {
            self.inputFolder = inputFolder
            self.outputFolder = outputFolder
            self.format = format
            self.range = range
            self.overwrite = overwrite
            self.recursive = recursive
            self.extensions = extensions
            self.options = options
        }
    }
}
